// features/auth.feature: signing out (a test of signing in itself, so it uses USERS and PASSWORD per PW-4)
import { PASSWORD, USERS, expect, expectStatus, test } from "../../fixtures";

test("Signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ request }) => {
  // Arrange: sign in so this client holds a session cookie
  await expectStatus(
    await request.post("/api/auth/login", { data: { email: USERS.member, password: PASSWORD } }),
    200,
  );
  const before = (await request.storageState()).cookies.map((c) => c.name);
  expect(before, "signed in with a session cookie").toContain("session");

  // Act
  const response = await request.post("/api/auth/logout");

  // Assert
  await expectStatus(response, 204);
  const cookie = response.headersArray().find((h) => h.name.toLowerCase() === "set-cookie");
  expect(cookie?.value, "logout sets a session cookie header").toMatch(/^session=(""|);/);
  expect(cookie?.value.toLowerCase()).toContain("max-age=0");
  // The client's cookie jar no longer holds a session.
  const after = (await request.storageState()).cookies.map((c) => c.name);
  expect(after).not.toContain("session");
});
